<?php require_once __DIR__.'/includes/bootstrap.php'; $pageTitle='FAQ | StudentHub'; include __DIR__.'/includes/header.php'; ?>
<main id="main-content"><section class="page-title"><h1>Frequently asked questions</h1><p>Quick answers to common StudentHub questions.</p></section><section class="section"><div id="faqList"><p>Loading FAQs…</p></div><p id="faqError" role="alert"></p></section></main>
<script>
document.addEventListener('DOMContentLoaded',async()=>{const list=document.getElementById('faqList');try{const r=await fetch('data/faqs.json');if(!r.ok)throw Error();const faqs=await r.json();list.replaceChildren();faqs.forEach((f,i)=>{const item=document.createElement('article');item.className='faq-item';const b=document.createElement('button');b.className='faq-question';b.textContent=f.question;b.id='faq-q-'+i;b.setAttribute('aria-expanded','false');b.setAttribute('aria-controls','faq-a-'+i);const a=document.createElement('div');a.className='faq-answer';a.id='faq-a-'+i;a.hidden=true;const p=document.createElement('p');p.textContent=f.answer;a.append(p);b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!open));a.hidden=open});item.append(b,a);list.append(item)})}catch(e){document.getElementById('faqError').textContent='FAQs could not be loaded.'}});
</script><?php include __DIR__.'/includes/footer.php'; ?>
